import{ModalEmpresaCtrl}from"../../modal/modalEmpresaCtrl.min.js";class EmpresaCtrl{static $inject=["$http","modalService"];constructor($http,_modalSvc){this.$http=$http,this._modalSvc=_modalSvc,this.empresas=[],this.accion={}}$onInit(){this.accion=JSON.parse(localStorage.getItem("accion")),null===this.accion?location.href="/Home/Index":this.accion=this.accion[0],this.initiload()}initiload(){showLoader(),this.$http.get("/Empresa/Get?json="+JSON.stringify({})).then(({data:response})=>{if("0"===response.id)return hideLoader(),void this._toastr.toastr("warning",response.message);this.empresas=JSON.parse(response.data)||[],hideLoader()})}openModal(item){const modalRef=this._modalSvc.openModalSecond(ModalEmpresaCtrl,"Empresa/_ModalEmpresa.cshtml","md",item);modalRef.result.then(response=>{"object"==typeof response&&"1"===response.id&&this.initiload()})}async delete(item){let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:`<small>Esta seguro de eliminar esta Empresa: <b>${item.razonSocial}</b></small>`,confirmButtonText:"Sí, eliminar",showDenyButton:!0,denyButtonText:"No, cancelar"});isConfirmed&&(showLoader(),this.$http.post("/Empresa/Delete?id="+item.idEmpresa).then(({data:response})=>{if("0"===response.id)return hideLoader(),void toastr.warning(response.message);"1"===response.id&&(hideLoader(),toastr.success(response.message,response.titleSms),this.initiload())}))}}export default app.controller("empresaCtrl",EmpresaCtrl).name;